// Read the adapter's one-shot checked-refinement text for an invalid input.
// The adapter resets it at every call, so a missing text keeps the fixed one.
const diagnosticSupport = `
def _graph_checked_status(status, diagnostic):
    if status != 1:
        return _graph_status(status)
    message = diagnostic()
    if message is None:
        return _graph_status(status)
    try:
        text = message.decode("utf-8")
    except UnicodeDecodeError:
        raise _GraphInvalidNative("Malformed native refinement diagnostic") from None
    raise LeanBridgeError(status, text)
`;

export const generateCopiedPythonGraphPackage = (ir, evidence = null, { refinementDiagnostics = false } = {}) => {
	const model = compileCopiedPythonGraphPackageModel(ir);
	const generated = { ...generateCopiedPythonGraphConversions(ir, { refinementDiagnostics })
		, refinementDiagnostics };

 * Whether the copied graph adapters export exact checked-refinement diagnostics.
 * Host wrappers must read them exactly when the adapter provides them.
 *
 * @param model - Verified native component model.
 */
export const nativeGraphRefinementDiagnostics = model => Boolean(model.copiedGraph)
	&& !model.copiedGraph.callbacks
	&& model.exports.some(item => item.refinements?.parameters?.some(Boolean));

